function screenPage(s) {
  return P(s.num, s.sec, `<h1 class="t">${s.title}</h1><p class="lead">${s.lead}</p>${chips(s.who)}
    ${frame(s.img, s.co, { crop: s.crop })}${legend(s.lg)}${s.q ? questions(s.q) : ''}
    <div class="row">${card('Do this', s.do, 'circle-check')}${card('Pro tip', s.tip, 'lightbulb', 'tip')}</div>`);
}

export function trainingDoc() {
  n = 1;
  const cover = `<section class="page cover"><div class="top">${LOGO} OutletOS</div>
    <div class="kicker">Product Training & User Guide · v2.0</div><h1>Run every<br/>restaurant like<br/>your best one.</h1>
    <p>From first sign-up to daily operations: a step-by-step setup guide, then every screen explained on one page, for owners, managers, chefs, cashiers, hosts and auditors.</p>
    <div class="roles">${['Owner', 'Area Manager', 'Branch Manager', 'Head Chef', 'Cashier / Captain', 'Line Cook', 'Host', 'Auditor', 'IT Admin'].map((r) => `<span>${r}</span>`).join('')}</div>
    <div class="mock">${frame('01-dashboard.jpg').replace('class="shot"', 'class="shot" style="margin:0;border:0"')}</div>
    <div class="meta"><span>7 setup steps</span><span>31 screens</span><span>9 roles</span><span>November 2026</span></div></section>`;

  const NAV = [['layout-dashboard', 'Overview', 'Dashboard · AI Agents'], ['concierge-bell', 'Front of house', 'Point of Sale · Reservations · Guests'], ['chef-hat', 'Kitchen & supply', 'Kitchen · Inventory & Menu · Food Safety'], ['users', 'People & vision', 'Vision Intelligence · Workforce'],
    ['shield-alert', 'Control & reporting', 'Alerts · Reports · Finance & Compliance'], ['settings', 'Administration', 'Access Control · Integrations']];
  const intro = P('', 'Start here', `<h1 class="t">How to use this guide</h1><p class="lead">Find your role below, start on the screen it opens, then read only the pages you use. Each page shows the real screen with numbered callouts, what to do daily and one pro tip.</p>
    <table class="r"><thead><tr><th>Role</th><th>Opens on</th><th>Chapters you’ll use</th></tr></thead><tbody>
    ${[['Owner', 'Setup, then Dashboard', 'Every chapter'], ['Area Manager', 'Dashboard (your region)', 'Dashboard, Reports, Finance, Inventory, Workforce, Alerts'], ['Branch Manager', 'Dashboard (your branch)', 'POS, Reservations, Inventory, Reports, Finance, Workforce'], ['Head Chef', 'Dashboard (operations)', 'Kitchen, Inventory & 86, Food Safety, Vision, Reports (ops)'], ['Cashier / Captain', 'Point of Sale', 'POS, Reservations, Guests'], ['Line Cook', 'Kitchen (your station)', 'Kitchen, Food Safety, Alerts'], ['Host', 'Guest Intelligence', 'Reservations, Guests, POS'], ['Food Safety Auditor', 'Vision Intelligence', 'Vision, Food Safety, Alerts'], ['IT Admin', 'Integrations', 'Integrations, Access Control']]
      .map(([r, o, p]) => `<tr><td><b>${r}</b></td><td>${o}</td><td>${p}</td></tr>`).join('')}</tbody></table>
    <h1 class="t" style="font-size:15pt;margin-top:8mm">The sidebar: six groups</h1><p class="lead" style="margin-top:1mm">Tap a group name to fold it; the panel button at the top collapses the whole menu to icons. Both choices are remembered on your device.</p>
    <div class="nav">${NAV.map(([ic, t, d]) => `<div class="n"><span class="ic">${icon(ic, { size: 16, color: '#D92D3A' })}</span><div><b>${t}</b><span>${d}</span></div></div>`).join('')}</div>
    <div class="steps"><div><i>STEP 1</i><b>Pick a branch</b><span>Use the picker at the top. Every page follows it.</span></div><div><i>STEP 2</i><b>Ask or read</b><span>Ask Maître, or read the signals: green, amber, red.</span></div><div><i>STEP 3</i><b>Act and resolve</b><span>Fix the issue, then approve or tap Done on the alert.</span></div></div>`);
  const setupIntro = P('', 'Set up your workspace', `<h1 class="t">Setting up OutletOS, step by step</h1><p class="lead">A new workspace is ready in about 15 minutes. The guided setup adapts to you: any country, any number of outlets, different floors, menus and teams in each. Every step saves itself, and only three things are required to launch.</p>
    <div class="steps">${[['1', 'Create the workspace', 'Owner name, business, email, password.'], ['2', 'Business profile', 'Type, outlet count, current POS, goals.'], ['3', 'Country & tax', 'Currency, tax engine, receipt IDs, fiscal year.'], ['4', 'Outlets', 'Addresses, seats, hours, budgets, licences.'], ['5', 'Floors & tables', 'Areas and numbered tables per outlet.'], ['6', 'Menu', 'Costed template, spreadsheet, or by hand.'], ['7', 'Team & roles', 'Rosters per outlet and scoped logins.'], ['8', 'Modules & targets', 'Switch on what you need; set food and labour %.'], ['9', 'Integrations & launch', 'Connect systems, check readiness, launch.']].map(([n, t, d]) => `<div><i>STEP ${n}</i><b>${t}</b><span>${d}</span></div>`).join('')}</div>
    <table class="r"><thead><tr><th>Required to launch</th><th>Recommended</th><th>Can wait until go-live</th></tr></thead><tbody><tr><td><b>Business name & country</b></td><td>Floor plans for dine-in outlets</td><td>Tax IDs on receipts (GSTIN, FSSAI, VAT…)</td></tr><tr><td><b>At least one outlet</b></td><td>Team invitations</td><td>Integration credentials</td></tr><tr><td><b>A menu</b></td><td>Targets and modules</td><td>Hardware: printers, KDS screens, terminals</td></tr></tbody></table>
    <div class="row">${card('Before you start', ['Outlet list with addresses and seats', 'Tax registrations (e.g. GSTIN per state, FSSAI per outlet)', 'Menu as a spreadsheet, or use the template', 'Names and emails of your managers'], 'clipboard-list')}${card('Good to know', 'Choosing a country sets the tax rate, whether prices include tax, receipt IDs, fiscal year, rounding and number format. Every value stays editable.', 'lightbulb', 'tip')}</div>`);
  const setup = SETUP.map((sc, i) => screenPage({ ...sc, num: `S${i + 1}` }));
  const screens = SCREENS.map((sc, i) => screenPage({ ...sc, num: String(i + 1).padStart(2, '0') }));   // screen numbers follow reading order

  const roles = P(String(SCREENS.length + 1).padStart(2, '0'), 'Role views', `<h1 class="t">Same app, a different view for every role</h1><p class="lead">Line cooks and hosts get a focused workspace with just what they need. Nothing else is loaded or sent to their screen.</p>
    <div class="rv"><div class="rvl">${icon('chef-hat', { size: 14, color: '#D92D3A' })} Line Cook · Restaurant 1 · Grill station</div>${frame('17-cook.jpg', [[382, 32], [110, 194], [360, 117], [430, 375]], { crop: [0, 420] })}<div class="c4">${legend([['One branch', 'Locked to their restaurant.'], ['Three pages', 'Kitchen, Food Safety, Alerts.'], ['Own station', 'Grill tickets only.'], ['Station tickets', 'Timed against each dish.']])}</div></div>
    <div class="rv"><div class="rvl">${icon('heart-handshake', { size: 14, color: '#D92D3A' })} Host · Restaurant 1</div>${frame('18-host.jpg', [[110, 106], [560, 205], [1060, 252], [560, 400]], { crop: [0, 420] })}<div class="c4">${legend([['Two pages', 'Guests and Alerts.'], ['Arrivals', 'Regulars as they walk in.'], ['Masked phones', 'Privacy by role.'], ['Suggestions', 'What to say and offer.']])}</div></div>
    <div class="row">${card('Why it matters', ['Less noise means faster service', 'Sensitive data stays with the people who need it', 'New staff are productive on day one'], 'target')}${card('Pro tip', 'Kitchen tablets work best signed in as a Line Cook in Midnight mode: big timers, no distractions.', 'lightbulb', 'tip')}</div>`);

  const ref = P('', 'Quick reference', `<h1 class="t">Glossary & quick reference</h1><p class="lead">The numbers you will see most, in plain language.</p>
    <div class="gl">${[['Net sales', 'Revenue since midnight, compared with the same time yesterday.'], ['Online share', 'Share of sales from delivery apps and your website.'], ['Prime cost', 'Food cost + labour cost as % of sales. Target: 60% or less.'], ['Food cost', 'Ingredient cost of what you sold, from your menu costs.'],
      ['TPPH', 'Transactions per person-hour: orders ÷ labour hours.'], ['Sales per labour hour', 'Revenue ÷ labour hours worked.'], ['On time', 'Share of dishes finished within their target time.'], ['Camera compliance', 'Share of reliable camera checks passed in the last 2 hours.'], ['Station coverage', 'Staffed seconds ÷ open seconds for each station.'],
      ['Cold chain', 'Fridges and freezers inside their safe range.'], ['Branch score', 'A 0–100 blend of sales, speed, hygiene, staffing, cold chain and reviews.'], ['Tier', 'Guest loyalty level: Gold, Silver, Regular or New.'], ['Exception', 'A camera check that failed, e.g. gloves not worn.'], ['Maître', 'The orchestrator agent: briefs specialist agents and gives one answer.'], ['Specialist agent', 'An AI agent for one module that reads only data your role may see.'], ['KOT', 'Kitchen order ticket: items sent to each kitchen station.'], ['NC bill', 'Non-chargeable (complimentary) bill, settled to house with a reason.'], ['86', 'Dish marked unavailable at a branch; hidden from POS and delivery menus.'], ['Par', 'Stock level to top up to: daily usage × (lead time + 2 days).'], ['KRI', 'Key risk indicator: a leading signal with amber/red thresholds and an owner.'], ['MAPE', 'Forecast error: average % difference between forecast and actual.'], ['CGST / SGST', 'India’s GST on restaurant bills: 2.5% central + 2.5% state.'], ['TCS', 'Tax collected at source by delivery platforms (0.5%).'], ['Audit tier', 'Camera checks too fine for ceiling CCTV; sampled for human review.']]
      .map(([t, d]) => `<div><b>${t}</b><span>${d}</span></div>`).join('')}</div>
    <div class="row">${card('Colour language', ['Green: on target', 'Amber: watch it', 'Red: act now', 'Violet: online channels · Orange: in-store'], 'palette')}${card('Need help?', ['Ask your Owner for access changes', 'Ask IT for new integrations or cameras', 'Missing a page? Your role may not include it'], 'book-open')}</div>`);

  return doc(TITLE, CSS, [cover, intro, setupIntro, ...setup, ...screens, roles, ref]);
}
